window.TOPICS=[{"id": "5bd23fa2c7da7596", "n": 1, "title": "Valuation — лекция IB Club", "sections": ["Valuation — лекция IB Club", "Valuation — лекция IB Club::1. Что такое стоимость", "Valuation — лекция IB Club::2. EV, Equity и мост", "Valuation — лекция IB Club::3. Модильяни–Миллер", "Valuation — лекция IB Club::4. Подходы к оценке", "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "Valuation — лекция IB Club::6. Мультипликаторы", "Valuation — лекция IB Club::7. Примеры из приложения"]}];
window.CARDS=[{"id": 1793123716078, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Что такое фундаментальная (intrinsic) стоимость?", "a": ["Что такое фундаментальная (intrinsic) стоимость? «Истинная», «реальная» стоимость актива. Её определяет тот, кто полностью понимает характеристики актива или компании. Пояснение: На слайде два определения: 1) «настоящая» стоимость, сглаживающая краткосрочные колебания цены; 2) результат оценки человеком с полным пониманием актива. Главный инструмент — DCF."], "frontHtml": "<div>Что такое фундаментальная (intrinsic) стоимость?</div>", "backHtml": "<div>Что такое фундаментальная (intrinsic) стоимость?</div><hr><div>«Истинная», «реальная» стоимость актива. Её определяет тот, кто полностью понимает характеристики актива или компании.</div><div><b>Пояснение:</b> На слайде два определения: 1) «настоящая» стоимость, сглаживающая краткосрочные колебания цены; 2) результат оценки человеком с полным пониманием актива. Главный инструмент — DCF.</div>"}, {"id": 1793123716080, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Что такое рыночная (market) стоимость?", "a": ["Что такое рыночная (market) стоимость? Цена, по которой актив перешёл бы от готового продавца к готовому покупателю, если оба информированы, действуют разумно и без принуждения. Пояснение: Определение из Международных стандартов оценки (IVS). Ориентируется на реальные рыночные сделки и котировки."], "frontHtml": "<div>Что такое рыночная (market) стоимость?</div>", "backHtml": "<div>Что такое рыночная (market) стоимость?</div><hr><div>Цена, по которой актив перешёл бы от готового продавца к готовому покупателю, если оба информированы, действуют разумно и без принуждения.</div><div><b>Пояснение:</b> Определение из Международных стандартов оценки (IVS). Ориентируется на реальные рыночные сделки и котировки.</div>"}, {"id": 1793123716082, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Что значит сделка на рыночных условиях (arm's-length)?", "a": ["Что значит сделка на рыночных условиях (arm's-length)? Сделка между независимыми сторонами без особых отношений между ними. Пояснение: Продажа компании родственнику или своей «дочке» — не arm's-length: цена может быть занижена или завышена не по рыночным причинам."], "frontHtml": "<div>Что значит сделка на рыночных условиях (arm&#x27;s-length)?</div>", "backHtml": "<div>Что значит сделка на рыночных условиях (arm&#x27;s-length)?</div><hr><div>Сделка между независимыми сторонами без особых отношений между ними.</div><div><b>Пояснение:</b> Продажа компании родственнику или своей «дочке» — не arm&#x27;s-length: цена может быть занижена или завышена не по рыночным причинам.</div>"}, {"id": 1793123716084, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Что такое инвестиционная (investment) стоимость?", "a": ["Что такое инвестиционная (investment) стоимость? Стоимость актива для конкретного покупателя с учётом его целей, синергий и условий сделки. Пояснение: У разных покупателей она разная. Холдинг, который сэкономит на закупках после покупки, готов заплатить больше, чем фонд без синергий."], "frontHtml": "<div>Что такое инвестиционная (investment) стоимость?</div>", "backHtml": "<div>Что такое инвестиционная (investment) стоимость?</div><hr><div>Стоимость актива для конкретного покупателя с учётом его целей, синергий и условий сделки.</div><div><b>Пояснение:</b> У разных покупателей она разная. Холдинг, который сэкономит на закупках после покупки, готов заплатить больше, чем фонд без синергий.</div>"}, {"id": 1793123716086, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Почему рыночная стоимость может отличаться от фундаментальной?", "a": ["Почему рыночная стоимость может отличаться от фундаментальной? Из-за неэффективности рынка: паники, хайпа, низкой ликвидности, недостатка информации. Пояснение: Пример: по DCF компания стоит 100, а на бирже — 80, потому что рынок сейчас пессимистичен."], "frontHtml": "<div>Почему рыночная стоимость может отличаться от фундаментальной?</div>", "backHtml": "<div>Почему рыночная стоимость может отличаться от фундаментальной?</div><hr><div>Из-за неэффективности рынка: паники, хайпа, низкой ликвидности, недостатка информации.</div><div><b>Пояснение:</b> Пример: по DCF компания стоит 100, а на бирже — 80, потому что рынок сейчас пессимистичен.</div>"}, {"id": 1793123716088, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Какие термины на слайде — синонимы фундаментальной стоимости?", "a": ["Какие термины на слайде — синонимы фундаментальной стоимости? Fair (справедливая), intrinsic (внутренняя), independent (независимая). Пояснение: Все три означают стоимость, посчитанную исходя из самого бизнеса, а не из текущей цены на рынке."], "frontHtml": "<div>Какие термины на слайде — синонимы фундаментальной стоимости?</div>", "backHtml": "<div>Какие термины на слайде — синонимы фундаментальной стоимости?</div><hr><div>Fair (справедливая), intrinsic (внутренняя), independent (независимая).</div><div><b>Пояснение:</b> Все три означают стоимость, посчитанную исходя из самого бизнеса, а не из текущей цены на рынке.</div>"}, {"id": 1793123716090, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::1. Что такое стоимость", "q": "Какое соотношение трёх видов стоимости обычно бывает в M&A?", "a": ["Какое соотношение трёх видов стоимости обычно бывает в M&A? Покупатель может заплатить больше рынка (премию), но не больше своей инвестиционной стоимости. Пояснение: Пример: рыночная 80, фундаментальная 100, инвестиционная для покупателя 120. Цена сделки обычно где-то между ними."], "frontHtml": "<div>Какое соотношение трёх видов стоимости обычно бывает в M&amp;A?</div>", "backHtml": "<div>Какое соотношение трёх видов стоимости обычно бывает в M&amp;A?</div><hr><div>Покупатель может заплатить больше рынка (премию), но не больше своей инвестиционной стоимости.</div><div><b>Пояснение:</b> Пример: рыночная 80, фундаментальная 100, инвестиционная для покупателя 120. Цена сделки обычно где-то между ними.</div>"}, {"id": 1793123716092, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Из чего состоят активы на упрощённом балансе (слайд 6)?", "a": ["Из чего состоят активы на упрощённом балансе (слайд 6)? Операционные активы, вложения в ассоциированные компании, денежные средства (cash), прочие активы. Пояснение: Слева на балансе — то, что у компании есть и куда вложены деньги (Uses)."], "frontHtml": "<div>Из чего состоят активы на упрощённом балансе (слайд 6)?</div>", "backHtml": "<div>Из чего состоят активы на упрощённом балансе (слайд 6)?</div><hr><div>Операционные активы, вложения в ассоциированные компании, денежные средства (cash), прочие активы.</div><div><b>Пояснение:</b> Слева на балансе — то, что у компании есть и куда вложены деньги (Uses).</div>"}, {"id": 1793123716094, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое операционные активы?", "a": ["Что такое операционные активы? Активы, на которых компания зарабатывает основной доход: заводы, оборудование, запасы, дебиторская задолженность. Пояснение: Именно их стоимость и есть Enterprise Value."], "frontHtml": "<div>Что такое операционные активы?</div>", "backHtml": "<div>Что такое операционные активы?</div><hr><div>Активы, на которых компания зарабатывает основной доход: заводы, оборудование, запасы, дебиторская задолженность.</div><div><b>Пояснение:</b> Именно их стоимость и есть Enterprise Value.</div>"}, {"id": 1793123716096, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Из чего состоят пассивы на упрощённом балансе?", "a": ["Из чего состоят пассивы на упрощённом балансе? Собственный капитал (equity), привилегированные акции, доли меньшинства (minority interest), долг, прочие обязательства. Пояснение: Справа на балансе — кто профинансировал активы (Sources of funding)."], "frontHtml": "<div>Из чего состоят пассивы на упрощённом балансе?</div>", "backHtml": "<div>Из чего состоят пассивы на упрощённом балансе?</div><hr><div>Собственный капитал (equity), привилегированные акции, доли меньшинства (minority interest), долг, прочие обязательства.</div><div><b>Пояснение:</b> Справа на балансе — кто профинансировал активы (Sources of funding).</div>"}, {"id": 1793123716098, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что означают Uses и Sources of funding (слайд 7)?", "a": ["Что означают Uses и Sources of funding (слайд 7)? Uses — куда вложены деньги (активы). Sources — откуда деньги взялись (пассивы). Пояснение: Обе стороны баланса всегда равны: всё, что есть у компании, кем-то профинансировано."], "frontHtml": "<div>Что означают Uses и Sources of funding (слайд 7)?</div>", "backHtml": "<div>Что означают Uses и Sources of funding (слайд 7)?</div><hr><div>Uses — куда вложены деньги (активы). Sources — откуда деньги взялись (пассивы).</div><div><b>Пояснение:</b> Обе стороны баланса всегда равны: всё, что есть у компании, кем-то профинансировано.</div>"}, {"id": 1793123716100, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое Enterprise Value (EV)?", "a": ["Что такое Enterprise Value (EV)? Стоимость всего операционного бизнеса — общая для всех инвесторов: акционеров, кредиторов, держателей префов, миноритариев. Пояснение: Квартира стоит 10 млн — это EV. Неважно, сколько на ней ипотеки."], "frontHtml": "<div>Что такое Enterprise Value (EV)?</div>", "backHtml": "<div>Что такое Enterprise Value (EV)?</div><hr><div>Стоимость всего операционного бизнеса — общая для всех инвесторов: акционеров, кредиторов, держателей префов, миноритариев.</div><div><b>Пояснение:</b> Квартира стоит 10 млн — это EV. Неважно, сколько на ней ипотеки.</div>"}, {"id": 1793123716102, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое Equity Value?", "a": ["Что такое Equity Value? Стоимость, которая принадлежит только обычным акционерам. Для публичной компании это рыночная капитализация. Пояснение: Квартира 10 млн, ипотека 6 млн → твоя доля (Equity) = 4 млн. Цена одной акции = Equity Value / число акций."], "frontHtml": "<div>Что такое Equity Value?</div>", "backHtml": "<div>Что такое Equity Value?</div><hr><div>Стоимость, которая принадлежит только обычным акционерам. Для публичной компании это рыночная капитализация.</div><div><b>Пояснение:</b> Квартира 10 млн, ипотека 6 млн → твоя доля (Equity) = 4 млн. Цена одной акции = Equity Value / число акций.</div>"}, {"id": 1793123716104, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое чистый долг (Net Debt)?", "a": ["Что такое чистый долг (Net Debt)? Долг минус денежные средства: Net Debt = Debt − Cash. Пояснение: Если кэша больше, чем долга, пишут «Net Cash» — как у SABIC в таблице на слайде 24."], "frontHtml": "<div>Что такое чистый долг (Net Debt)?</div>", "backHtml": "<div>Что такое чистый долг (Net Debt)?</div><hr><div>Долг минус денежные средства: Net Debt = Debt − Cash.</div><div><b>Пояснение:</b> Если кэша больше, чем долга, пишут «Net Cash» — как у SABIC в таблице на слайде 24.</div>"}, {"id": 1793123716106, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое привилегированные акции (preferred stock)?", "a": ["Что такое привилегированные акции (preferred stock)? Акции с фиксированным дивидендом, который выплачивается раньше, чем по обычным акциям. Обычно без права голоса. Пояснение: Гибрид долга и акции. При ликвидации префы тоже получают деньги раньше обычных акционеров."], "frontHtml": "<div>Что такое привилегированные акции (preferred stock)?</div>", "backHtml": "<div>Что такое привилегированные акции (preferred stock)?</div><hr><div>Акции с фиксированным дивидендом, который выплачивается раньше, чем по обычным акциям. Обычно без права голоса.</div><div><b>Пояснение:</b> Гибрид долга и акции. При ликвидации префы тоже получают деньги раньше обычных акционеров.</div>"}, {"id": 1793123716108, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое доля меньшинства (minority interest)?", "a": ["Что такое доля меньшинства (minority interest)? Часть дочерней компании, которая принадлежит не тебе, а другим акционерам. Пояснение: Холдинг владеет 80% дочки, но включает её в отчётность на 100%. Оставшиеся 20% чужие — это minority interest."], "frontHtml": "<div>Что такое доля меньшинства (minority interest)?</div>", "backHtml": "<div>Что такое доля меньшинства (minority interest)?</div><hr><div>Часть дочерней компании, которая принадлежит не тебе, а другим акционерам.</div><div><b>Пояснение:</b> Холдинг владеет 80% дочки, но включает её в отчётность на 100%. Оставшиеся 20% чужие — это minority interest.</div>"}, {"id": 1793123716110, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое вложения в ассоциированные компании (investments in associates)?", "a": ["Что такое вложения в ассоциированные компании (investments in associates)? Доля 20–50% в другой компании — значимое влияние, но без контроля. Пояснение: Её выручка и EBITDA не входят в отчётность владельца, он получает только свою долю прибыли одной строкой."], "frontHtml": "<div>Что такое вложения в ассоциированные компании (investments in associates)?</div>", "backHtml": "<div>Что такое вложения в ассоциированные компании (investments in associates)?</div><hr><div>Доля 20–50% в другой компании — значимое влияние, но без контроля.</div><div><b>Пояснение:</b> Её выручка и EBITDA не входят в отчётность владельца, он получает только свою долю прибыли одной строкой.</div>"}, {"id": 1793123716112, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Что такое мост EV → Equity (EV to Equity bridge)?", "a": ["Что такое мост EV → Equity (EV to Equity bridge)? Расчёт, который переводит EV в Equity Value: Equity = EV − Долг + Cash − Префы − Minority interest + Associates. Пояснение: Нужен, потому что DCF по FCFF и EV/EBITDA дают EV, а цену акции считают от Equity. Работает и в обратную сторону."], "frontHtml": "<div>Что такое мост EV → Equity (EV to Equity bridge)?</div>", "backHtml": "<div>Что такое мост EV → Equity (EV to Equity bridge)?</div><hr><div>Расчёт, который переводит EV в Equity Value: Equity = EV − Долг + Cash − Префы − Minority interest + Associates.</div><div><b>Пояснение:</b> Нужен, потому что DCF по FCFF и EV/EBITDA дают EV, а цену акции считают от Equity. Работает и в обратную сторону.</div>"}, {"id": 1793123716114, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Почему в мосту долг и префы вычитаются?", "a": ["Почему в мосту долг и префы вычитаются? Это требования других инвесторов, которые стоят в очереди раньше обычных акционеров. Пояснение: Сначала расплачиваются с кредиторами и держателями префов, акционерам достаётся остаток."], "frontHtml": "<div>Почему в мосту долг и префы вычитаются?</div>", "backHtml": "<div>Почему в мосту долг и префы вычитаются?</div><hr><div>Это требования других инвесторов, которые стоят в очереди раньше обычных акционеров.</div><div><b>Пояснение:</b> Сначала расплачиваются с кредиторами и держателями префов, акционерам достаётся остаток.</div>"}, {"id": 1793123716116, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Почему в мосту minority interest вычитается?", "a": ["Почему в мосту minority interest вычитается? EBITDA дочки включена на 100%, а значит, в EV попала чужая доля — её нужно убрать. Пояснение: Дочка на 80% стоит 500 → вычитаешь 20% × 500 = 100."], "frontHtml": "<div>Почему в мосту minority interest вычитается?</div>", "backHtml": "<div>Почему в мосту minority interest вычитается?</div><hr><div>EBITDA дочки включена на 100%, а значит, в EV попала чужая доля — её нужно убрать.</div><div><b>Пояснение:</b> Дочка на 80% стоит 500 → вычитаешь 20% × 500 = 100.</div>"}, {"id": 1793123716118, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Почему в мосту investments in associates прибавляются (вопрос «???» на слайде 8)?", "a": ["Почему в мосту investments in associates прибавляются (вопрос «???» на слайде 8)? Их EBITDA не входит в EBITDA компании, поэтому DCF и EV/EBITDA их не учли — а доля принадлежит акционерам. Пояснение: Зеркально minority interest: там в EBITDA попало лишнее (−), здесь не попало своё (+)."], "frontHtml": "<div>Почему в мосту investments in associates прибавляются (вопрос «???» на слайде 8)?</div>", "backHtml": "<div>Почему в мосту investments in associates прибавляются (вопрос «???» на слайде 8)?</div><hr><div>Их EBITDA не входит в EBITDA компании, поэтому DCF и EV/EBITDA их не учли — а доля принадлежит акционерам.</div><div><b>Пояснение:</b> Зеркально minority interest: там в EBITDA попало лишнее (−), здесь не попало своё (+).</div>"}, {"id": 1793123716120, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::2. EV, Equity и мост", "q": "Посчитай Equity Value: EV 1000, долг 350, cash 50, префы 50, minority 100, associates 60.", "a": ["Посчитай Equity Value: EV 1000, долг 350, cash 50, префы 50, minority 100, associates 60. 1000 − 350 + 50 − 50 − 100 + 60 = 610. Пояснение: Порядок не важен, важны знаки: кэш и associates — плюс, всё остальное — минус."], "frontHtml": "<div>Посчитай Equity Value: EV 1000, долг 350, cash 50, префы 50, minority 100, associates 60.</div>", "backHtml": "<div>Посчитай Equity Value: EV 1000, долг 350, cash 50, префы 50, minority 100, associates 60.</div><hr><div>1000 − 350 + 50 − 50 − 100 + 60 = 610.</div><div><b>Пояснение:</b> Порядок не важен, важны знаки: кэш и associates — плюс, всё остальное — минус.</div>"}, {"id": 1793123716122, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое структура капитала?", "a": ["Что такое структура капитала? Соотношение долга и собственного капитала, на которые финансируется компания. Пояснение: Долг 400, капитал 600 → D/E = 400/600 ≈ 0,67."], "frontHtml": "<div>Что такое структура капитала?</div>", "backHtml": "<div>Что такое структура капитала?</div><hr><div>Соотношение долга и собственного капитала, на которые финансируется компания.</div><div><b>Пояснение:</b> Долг 400, капитал 600 → D/E = 400/600 ≈ 0,67.</div>"}, {"id": 1793123716124, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что говорит теорема Модильяни–Миллера без налогов?", "a": ["Что говорит теорема Модильяни–Миллера без налогов? Стоимость компании не зависит от того, сколько у неё долга: EV = Equity + Debt. Пояснение: Стоимость создаёт бизнес, а долг только решает, кому сколько достанется. Пиццу можно порезать на 4 или 8 кусков — больше она не станет. Это «принцип нерелевантности структуры капитала»."], "frontHtml": "<div>Что говорит теорема Модильяни–Миллера без налогов?</div>", "backHtml": "<div>Что говорит теорема Модильяни–Миллера без налогов?</div><hr><div>Стоимость компании не зависит от того, сколько у неё долга: EV = Equity + Debt.</div><div><b>Пояснение:</b> Стоимость создаёт бизнес, а долг только решает, кому сколько достанется. Пиццу можно порезать на 4 или 8 кусков — больше она не станет. Это «принцип нерелевантности структуры капитала».</div>"}, {"id": 1793123716126, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое налоговый щит (tax shield)?", "a": ["Что такое налоговый щит (tax shield)? Экономия на налоге, которую даёт долг: проценты по кредиту уменьшают налогооблагаемую прибыль. Пояснение: Прибыль 100, налог 25%. Без долга налог 25. С процентами 40 налог считается с 60 и равен 15. Экономия 10 — это налоговый щит."], "frontHtml": "<div>Что такое налоговый щит (tax shield)?</div>", "backHtml": "<div>Что такое налоговый щит (tax shield)?</div><hr><div>Экономия на налоге, которую даёт долг: проценты по кредиту уменьшают налогооблагаемую прибыль.</div><div><b>Пояснение:</b> Прибыль 100, налог 25%. Без долга налог 25. С процентами 40 налог считается с 60 и равен 15. Экономия 10 — это налоговый щит.</div>"}, {"id": 1793123716128, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Почему налоговый щит есть у долга, но нет у акционерного капитала?", "a": ["Почему налоговый щит есть у долга, но нет у акционерного капитала? Проценты по долгу вычитаются из прибыли до налога, а дивиденды платятся из прибыли после налога. Пояснение: Поэтому финансировать бизнес долгом с точки зрения налогов дешевле."], "frontHtml": "<div>Почему налоговый щит есть у долга, но нет у акционерного капитала?</div>", "backHtml": "<div>Почему налоговый щит есть у долга, но нет у акционерного капитала?</div><hr><div>Проценты по долгу вычитаются из прибыли до налога, а дивиденды платятся из прибыли после налога.</div><div><b>Пояснение:</b> Поэтому финансировать бизнес долгом с точки зрения налогов дешевле.</div>"}, {"id": 1793123716130, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что говорит теорема Модильяни–Миллера с налогами?", "a": ["Что говорит теорема Модильяни–Миллера с налогами? Чем больше долга, тем выше стоимость компании: EV = Equity + Debt + TS, где TS — приведённая стоимость налогового щита. Пояснение: То есть стоимость с долгом = стоимость без долга + налоговый щит. На графике это растущая прямая."], "frontHtml": "<div>Что говорит теорема Модильяни–Миллера с налогами?</div>", "backHtml": "<div>Что говорит теорема Модильяни–Миллера с налогами?</div><hr><div>Чем больше долга, тем выше стоимость компании: EV = Equity + Debt + TS, где TS — приведённая стоимость налогового щита.</div><div><b>Пояснение:</b> То есть стоимость с долгом = стоимость без долга + налоговый щит. На графике это растущая прямая.</div>"}, {"id": 1793123716132, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Чему равна приведённая стоимость налогового щита при постоянном долге?", "a": ["Чему равна приведённая стоимость налогового щита при постоянном долге? PV(TS) = T × D — ставка налога, умноженная на сумму долга. Пояснение: Пример: налог 25%, долг 400 → налоговый щит стоит 100. Если долг вечный, вся будущая экономия на налогах в сумме стоит ровно столько."], "frontHtml": "<div>Чему равна приведённая стоимость налогового щита при постоянном долге?</div>", "backHtml": "<div>Чему равна приведённая стоимость налогового щита при постоянном долге?</div><hr><div>PV(TS) = T × D — ставка налога, умноженная на сумму долга.</div><div><b>Пояснение:</b> Пример: налог 25%, долг 400 → налоговый щит стоит 100. Если долг вечный, вся будущая экономия на налогах в сумме стоит ровно столько.</div>"}, {"id": 1793123716134, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Почему вывод «ММ с налогами» нереалистичен?", "a": ["Почему вывод «ММ с налогами» нереалистичен? Из него следует, что оптимально финансироваться почти на 100% долгом, а это ведёт к банкротству. Пояснение: Модель не учитывает издержки финансовых трудностей — их добавляет следующий шаг (слайд 12)."], "frontHtml": "<div>Почему вывод «ММ с налогами» нереалистичен?</div>", "backHtml": "<div>Почему вывод «ММ с налогами» нереалистичен?</div><hr><div>Из него следует, что оптимально финансироваться почти на 100% долгом, а это ведёт к банкротству.</div><div><b>Пояснение:</b> Модель не учитывает издержки финансовых трудностей — их добавляет следующий шаг (слайд 12).</div>"}, {"id": 1793123716136, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое финансовые трудности (financial distress)?", "a": ["Что такое финансовые трудности (financial distress)? Ситуация, когда у компании слишком много долга и появляется риск, что она не сможет его выплатить. Пояснение: Это ещё не банкротство, а состояние «на грани», когда все вокруг начинают опасаться за компанию."], "frontHtml": "<div>Что такое финансовые трудности (financial distress)?</div>", "backHtml": "<div>Что такое финансовые трудности (financial distress)?</div><hr><div>Ситуация, когда у компании слишком много долга и появляется риск, что она не сможет его выплатить.</div><div><b>Пояснение:</b> Это ещё не банкротство, а состояние «на грани», когда все вокруг начинают опасаться за компанию.</div>"}, {"id": 1793123716138, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое прямые издержки финансовых трудностей?", "a": ["Что такое прямые издержки финансовых трудностей? Расходы на сам процесс банкротства: юристы, суды, арбитражный управляющий, продажа имущества по низкой цене."], "frontHtml": "<div>Что такое прямые издержки финансовых трудностей?</div>", "backHtml": "<div>Что такое прямые издержки финансовых трудностей?</div><hr><div>Расходы на сам процесс банкротства: юристы, суды, арбитражный управляющий, продажа имущества по низкой цене.</div>"}, {"id": 1793123716140, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое косвенные издержки финансовых трудностей?", "a": ["Что такое косвенные издержки финансовых трудностей? Потери бизнеса из-за того, что компания выглядит ненадёжной: уходят клиенты и сотрудники, поставщики требуют предоплату, банки поднимают ставки. Пояснение: Обычно они намного больше прямых и начинаются ещё до банкротства."], "frontHtml": "<div>Что такое косвенные издержки финансовых трудностей?</div>", "backHtml": "<div>Что такое косвенные издержки финансовых трудностей?</div><hr><div>Потери бизнеса из-за того, что компания выглядит ненадёжной: уходят клиенты и сотрудники, поставщики требуют предоплату, банки поднимают ставки.</div><div><b>Пояснение:</b> Обычно они намного больше прямых и начинаются ещё до банкротства.</div>"}, {"id": 1793123716142, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Как выглядит итоговая формула стоимости на слайде 12 (ММ + издержки трудностей)?", "a": ["Как выглядит итоговая формула стоимости на слайде 12 (ММ + издержки трудностей)? EV = Equity + Debt + TS − CoFD, где TS — PV налогового щита, CoFD — PV издержек финансовых трудностей. Пояснение: Иначе: стоимость = стоимость без долга + плюс от долга − минус от долга."], "frontHtml": "<div>Как выглядит итоговая формула стоимости на слайде 12 (ММ + издержки трудностей)?</div>", "backHtml": "<div>Как выглядит итоговая формула стоимости на слайде 12 (ММ + издержки трудностей)?</div><hr><div>EV = Equity + Debt + TS − CoFD, где TS — PV налогового щита, CoFD — PV издержек финансовых трудностей.</div><div><b>Пояснение:</b> Иначе: стоимость = стоимость без долга + плюс от долга − минус от долга.</div>"}, {"id": 1793123716144, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое теория компромисса (trade-off theory)?", "a": ["Что такое теория компромисса (trade-off theory)? Теория, по которой компания выбирает размер долга, взвешивая плюс (налоговый щит) и минус (риск финансовых трудностей). Пояснение: Немного долга полезно — экономит налоги. Слишком много вредно — растёт риск банкротства. Компромисс — найти середину."], "frontHtml": "<div>Что такое теория компромисса (trade-off theory)?</div>", "backHtml": "<div>Что такое теория компромисса (trade-off theory)?</div><hr><div>Теория, по которой компания выбирает размер долга, взвешивая плюс (налоговый щит) и минус (риск финансовых трудностей).</div><div><b>Пояснение:</b> Немного долга полезно — экономит налоги. Слишком много вредно — растёт риск банкротства. Компромисс — найти середину.</div>"}, {"id": 1793123716146, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Что такое оптимальная структура капитала?", "a": ["Что такое оптимальная структура капитала? Соотношение долга и капитала, при котором стоимость компании максимальна. Пояснение: На графике со слайда 12 это вершина синей кривой: дальше каждый новый рубль долга добавляет издержек больше, чем экономит налогов."], "frontHtml": "<div>Что такое оптимальная структура капитала?</div>", "backHtml": "<div>Что такое оптимальная структура капитала?</div><hr><div>Соотношение долга и капитала, при котором стоимость компании максимальна.</div><div><b>Пояснение:</b> На графике со слайда 12 это вершина синей кривой: дальше каждый новый рубль долга добавляет издержек больше, чем экономит налогов.</div>"}, {"id": 1793123716148, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::3. Модильяни–Миллер", "q": "Какие компании могут держать много долга, а какие — мало?", "a": ["Какие компании могут держать много долга, а какие — мало? Много — со стабильными потоками и твёрдыми активами (электросети, недвижимость). Мало — те, чья ценность в людях и росте (IT, фарма). Пояснение: У вторых при трудностях стоимость тает быстрее, поэтому издержки трудностей для них выше."], "frontHtml": "<div>Какие компании могут держать много долга, а какие — мало?</div>", "backHtml": "<div>Какие компании могут держать много долга, а какие — мало?</div><hr><div>Много — со стабильными потоками и твёрдыми активами (электросети, недвижимость). Мало — те, чья ценность в людях и росте (IT, фарма).</div><div><b>Пояснение:</b> У вторых при трудностях стоимость тает быстрее, поэтому издержки трудностей для них выше.</div>"}, {"id": 1793123716150, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Какие три основных подхода к оценке существуют?", "a": ["Какие три основных подхода к оценке существуют? Доходный (income), рыночный (market) и затратный (cost). Пояснение: Плюс отдельная группа «другие»: SOTP, NAV, LBO-оценка."], "frontHtml": "<div>Какие три основных подхода к оценке существуют?</div>", "backHtml": "<div>Какие три основных подхода к оценке существуют?</div><hr><div>Доходный (income), рыночный (market) и затратный (cost).</div><div><b>Пояснение:</b> Плюс отдельная группа «другие»: SOTP, NAV, LBO-оценка.</div>"}, {"id": 1793123716152, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое доходный подход и какие методы в него входят?", "a": ["Что такое доходный подход и какие методы в него входят? Оценка по будущим доходам, которые принесёт бизнес. Методы: DCF (FCFF/FCFE), DDM, EVA, EMV. Пояснение: Даёт фундаментальную стоимость."], "frontHtml": "<div>Что такое доходный подход и какие методы в него входят?</div>", "backHtml": "<div>Что такое доходный подход и какие методы в него входят?</div><hr><div>Оценка по будущим доходам, которые принесёт бизнес. Методы: DCF (FCFF/FCFE), DDM, EVA, EMV.</div><div><b>Пояснение:</b> Даёт фундаментальную стоимость.</div>"}, {"id": 1793123716154, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое DCF?", "a": ["Что такое DCF? Discounted Cash Flow — оценка через дисконтирование будущих денежных потоков к сегодняшнему дню. Пояснение: Стоимость = сумма приведённых потоков за прогнозный период + приведённая терминальная стоимость."], "frontHtml": "<div>Что такое DCF?</div>", "backHtml": "<div>Что такое DCF?</div><hr><div>Discounted Cash Flow — оценка через дисконтирование будущих денежных потоков к сегодняшнему дню.</div><div><b>Пояснение:</b> Стоимость = сумма приведённых потоков за прогнозный период + приведённая терминальная стоимость.</div>"}, {"id": 1793123716156, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Чем отличаются FCFF и FCFE?", "a": ["Чем отличаются FCFF и FCFE? FCFF — свободный поток для всех инвесторов (до выплат по долгу), дисконтируется по WACC и даёт EV. FCFE — поток только для акционеров (после выплат по долгу), дисконтируется по стоимости капитала и даёт Equity. Пояснение: FCFF = Free Cash Flow to Firm, FCFE = Free Cash Flow to Equity. В банках чаще считают через FCFF."], "frontHtml": "<div>Чем отличаются FCFF и FCFE?</div>", "backHtml": "<div>Чем отличаются FCFF и FCFE?</div><hr><div>FCFF — свободный поток для всех инвесторов (до выплат по долгу), дисконтируется по WACC и даёт EV. FCFE — поток только для акционеров (после выплат по долгу), дисконтируется по стоимости капитала и даёт Equity.</div><div><b>Пояснение:</b> FCFF = Free Cash Flow to Firm, FCFE = Free Cash Flow to Equity. В банках чаще считают через FCFF.</div>"}, {"id": 1793123716158, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое DDM?", "a": ["Что такое DDM? Dividend Discount Model — оценка акции как приведённой стоимости всех будущих дивидендов. Пояснение: Подходит для компаний со стабильными дивидендами: банков, коммунальных компаний."], "frontHtml": "<div>Что такое DDM?</div>", "backHtml": "<div>Что такое DDM?</div><hr><div>Dividend Discount Model — оценка акции как приведённой стоимости всех будущих дивидендов.</div><div><b>Пояснение:</b> Подходит для компаний со стабильными дивидендами: банков, коммунальных компаний.</div>"}, {"id": 1793123716160, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое EVA?", "a": ["Что такое EVA? Economic Value Added — прибыль сверх стоимости капитала: EVA = NOPAT − WACC × вложенный капитал. Пояснение: Показывает, создаёт ли компания стоимость. Стоимость компании = вложенный капитал + приведённая стоимость будущих EVA."], "frontHtml": "<div>Что такое EVA?</div>", "backHtml": "<div>Что такое EVA?</div><hr><div>Economic Value Added — прибыль сверх стоимости капитала: EVA = NOPAT − WACC × вложенный капитал.</div><div><b>Пояснение:</b> Показывает, создаёт ли компания стоимость. Стоимость компании = вложенный капитал + приведённая стоимость будущих EVA.</div>"}, {"id": 1793123716162, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое EMV?", "a": ["Что такое EMV? Expected Monetary Value — взвешенная по вероятностям стоимость нескольких сценариев. Пояснение: Используют, когда исход бинарный: разведка месторождения, клинические испытания лекарства. Пример: 30% × 500 + 70% × 0 = 150."], "frontHtml": "<div>Что такое EMV?</div>", "backHtml": "<div>Что такое EMV?</div><hr><div>Expected Monetary Value — взвешенная по вероятностям стоимость нескольких сценариев.</div><div><b>Пояснение:</b> Используют, когда исход бинарный: разведка месторождения, клинические испытания лекарства. Пример: 30% × 500 + 70% × 0 = 150.</div>"}, {"id": 1793123716164, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое рыночный подход и какие методы в него входят?", "a": ["Что такое рыночный подход и какие методы в него входят? Оценка по тому, сколько платят на рынке за эту или похожие компании. Методы: рыночная цена (52W H/L), VWAP, trading comps, precedent transactions. Пояснение: Даёт рыночную стоимость. Comps и precedents называют методами относительной оценки (relative valuation)."], "frontHtml": "<div>Что такое рыночный подход и какие методы в него входят?</div>", "backHtml": "<div>Что такое рыночный подход и какие методы в него входят?</div><hr><div>Оценка по тому, сколько платят на рынке за эту или похожие компании. Методы: рыночная цена (52W H/L), VWAP, trading comps, precedent transactions.</div><div><b>Пояснение:</b> Даёт рыночную стоимость. Comps и precedents называют методами относительной оценки (relative valuation).</div>"}, {"id": 1793123716166, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое 52W High/Low?", "a": ["Что такое 52W High/Low? Максимальная и минимальная цена акции за последние 52 недели (год). Пояснение: Показывает диапазон, в котором рынок оценивал компанию, — ориентир для цены сделки."], "frontHtml": "<div>Что такое 52W High/Low?</div>", "backHtml": "<div>Что такое 52W High/Low?</div><hr><div>Максимальная и минимальная цена акции за последние 52 недели (год).</div><div><b>Пояснение:</b> Показывает диапазон, в котором рынок оценивал компанию, — ориентир для цены сделки.</div>"}, {"id": 1793123716168, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое VWAP?", "a": ["Что такое VWAP? Volume-Weighted Average Price — средняя цена акции за период, взвешенная по объёму торгов. Пояснение: Дни с большими объёмами весят больше. Обычно смотрят 1M, 6M, 12M VWAP, чтобы сгладить случайные скачки цены."], "frontHtml": "<div>Что такое VWAP?</div>", "backHtml": "<div>Что такое VWAP?</div><hr><div>Volume-Weighted Average Price — средняя цена акции за период, взвешенная по объёму торгов.</div><div><b>Пояснение:</b> Дни с большими объёмами весят больше. Обычно смотрят 1M, 6M, 12M VWAP, чтобы сгладить случайные скачки цены.</div>"}, {"id": 1793123716170, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое trading comps (торговые мультипликаторы)?", "a": ["Что такое trading comps (торговые мультипликаторы)? Оценка по мультипликаторам похожих публичных компаний, которые сейчас торгуются на бирже. Пояснение: Пример — слайд 26: EV/EBITDA и P/E коммунальных и энергетических компаний."], "frontHtml": "<div>Что такое trading comps (торговые мультипликаторы)?</div>", "backHtml": "<div>Что такое trading comps (торговые мультипликаторы)?</div><hr><div>Оценка по мультипликаторам похожих публичных компаний, которые сейчас торгуются на бирже.</div><div><b>Пояснение:</b> Пример — слайд 26: EV/EBITDA и P/E коммунальных и энергетических компаний.</div>"}, {"id": 1793123716172, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое precedent transactions (сделки-аналоги)?", "a": ["Что такое precedent transactions (сделки-аналоги)? Оценка по мультипликаторам, по которым в прошлом покупали похожие компании. Пояснение: Обычно дают более высокую оценку, чем trading comps, потому что в цену сделки входит премия за контроль."], "frontHtml": "<div>Что такое precedent transactions (сделки-аналоги)?</div>", "backHtml": "<div>Что такое precedent transactions (сделки-аналоги)?</div><hr><div>Оценка по мультипликаторам, по которым в прошлом покупали похожие компании.</div><div><b>Пояснение:</b> Обычно дают более высокую оценку, чем trading comps, потому что в цену сделки входит премия за контроль.</div>"}, {"id": 1793123716174, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое затратный подход и какие методы в него входят?", "a": ["Что такое затратный подход и какие методы в него входят? Оценка по стоимости активов компании. Методы: балансовая стоимость, ликвидационная стоимость, стоимость строительства (historical capex). Пояснение: Не учитывает будущие доходы, поэтому для действующего прибыльного бизнеса обычно занижает стоимость."], "frontHtml": "<div>Что такое затратный подход и какие методы в него входят?</div>", "backHtml": "<div>Что такое затратный подход и какие методы в него входят?</div><hr><div>Оценка по стоимости активов компании. Методы: балансовая стоимость, ликвидационная стоимость, стоимость строительства (historical capex).</div><div><b>Пояснение:</b> Не учитывает будущие доходы, поэтому для действующего прибыльного бизнеса обычно занижает стоимость.</div>"}, {"id": 1793123716176, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое балансовая (book) стоимость?", "a": ["Что такое балансовая (book) стоимость? Стоимость активов минус обязательства по данным бухгалтерского баланса. Пояснение: Отражает историческую цену покупки активов, а не их текущую ценность."], "frontHtml": "<div>Что такое балансовая (book) стоимость?</div>", "backHtml": "<div>Что такое балансовая (book) стоимость?</div><hr><div>Стоимость активов минус обязательства по данным бухгалтерского баланса.</div><div><b>Пояснение:</b> Отражает историческую цену покупки активов, а не их текущую ценность.</div>"}, {"id": 1793123716178, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое ликвидационная стоимость?", "a": ["Что такое ликвидационная стоимость? Сколько можно выручить, если быстро продать все активы по отдельности и расплатиться с долгами. Пояснение: Обычно это нижняя граница оценки — «пол»."], "frontHtml": "<div>Что такое ликвидационная стоимость?</div>", "backHtml": "<div>Что такое ликвидационная стоимость?</div><hr><div>Сколько можно выручить, если быстро продать все активы по отдельности и расплатиться с долгами.</div><div><b>Пояснение:</b> Обычно это нижняя граница оценки — «пол».</div>"}, {"id": 1793123716180, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое оценка по стоимости строительства (historical capex / cost to build)?", "a": ["Что такое оценка по стоимости строительства (historical capex / cost to build)? Сколько нужно потратить, чтобы построить такой же бизнес с нуля. Пояснение: Логика: покупатель не заплатит больше, чем стоит построить то же самое самому."], "frontHtml": "<div>Что такое оценка по стоимости строительства (historical capex / cost to build)?</div>", "backHtml": "<div>Что такое оценка по стоимости строительства (historical capex / cost to build)?</div><hr><div>Сколько нужно потратить, чтобы построить такой же бизнес с нуля.</div><div><b>Пояснение:</b> Логика: покупатель не заплатит больше, чем стоит построить то же самое самому.</div>"}, {"id": 1793123716182, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое SOTP?", "a": ["Что такое SOTP? Sum-of-the-Parts — оценка компании по частям: каждый сегмент оценивают отдельно своим методом, а результаты складывают. Пояснение: Подходит для конгломератов, где сегменты очень разные (например, нефтехимия + энергетика)."], "frontHtml": "<div>Что такое SOTP?</div>", "backHtml": "<div>Что такое SOTP?</div><hr><div>Sum-of-the-Parts — оценка компании по частям: каждый сегмент оценивают отдельно своим методом, а результаты складывают.</div><div><b>Пояснение:</b> Подходит для конгломератов, где сегменты очень разные (например, нефтехимия + энергетика).</div>"}, {"id": 1793123716184, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое NAV?", "a": ["Что такое NAV? Net Asset Value — рыночная стоимость всех активов минус обязательства. Пояснение: Применяют для холдингов, фондов, девелоперов, добывающих компаний (стоимость запасов)."], "frontHtml": "<div>Что такое NAV?</div>", "backHtml": "<div>Что такое NAV?</div><hr><div>Net Asset Value — рыночная стоимость всех активов минус обязательства.</div><div><b>Пояснение:</b> Применяют для холдингов, фондов, девелоперов, добывающих компаний (стоимость запасов).</div>"}, {"id": 1793123716186, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::4. Подходы к оценке", "q": "Что такое LBO-оценка?", "a": ["Что такое LBO-оценка? Оценка того, сколько может заплатить фонд прямых инвестиций при покупке компании преимущественно в долг, чтобы получить целевую доходность (обычно 20–25% IRR). Пояснение: LBO = Leveraged Buyout, выкуп с использованием заёмных средств. Даёт ориентир минимальной цены, которую готов дать финансовый покупатель."], "frontHtml": "<div>Что такое LBO-оценка?</div>", "backHtml": "<div>Что такое LBO-оценка?</div><hr><div>Оценка того, сколько может заплатить фонд прямых инвестиций при покупке компании преимущественно в долг, чтобы получить целевую доходность (обычно 20–25% IRR).</div><div><b>Пояснение:</b> LBO = Leveraged Buyout, выкуп с использованием заёмных средств. Даёт ориентир минимальной цены, которую готов дать финансовый покупатель.</div>"}, {"id": 1793123716188, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое временная стоимость денег?", "a": ["Что такое временная стоимость денег? Рубль сегодня стоит больше, чем рубль в будущем. Пояснение: Сегодняшние деньги можно вложить и заработать, плюс есть инфляция и риск не получить их потом. Поэтому 1 млн сегодня лучше, чем 1 млн через год."], "frontHtml": "<div>Что такое временная стоимость денег?</div>", "backHtml": "<div>Что такое временная стоимость денег?</div><hr><div>Рубль сегодня стоит больше, чем рубль в будущем.</div><div><b>Пояснение:</b> Сегодняшние деньги можно вложить и заработать, плюс есть инфляция и риск не получить их потом. Поэтому 1 млн сегодня лучше, чем 1 млн через год.</div>"}, {"id": 1793123716190, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что выбрать: 1 млн руб. сегодня или 1,2 млн через год?", "a": ["Что выбрать: 1 млн руб. сегодня или 1,2 млн через год? Зависит от того, сколько можно заработать на деньгах за год (ставки дисконтирования). Если больше 20% — лучше сегодня, если меньше — через год. Пояснение: При ставке 20% 1,2 млн через год стоят сегодня ровно 1,2 / 1,2 = 1 млн."], "frontHtml": "<div>Что выбрать: 1 млн руб. сегодня или 1,2 млн через год?</div>", "backHtml": "<div>Что выбрать: 1 млн руб. сегодня или 1,2 млн через год?</div><hr><div>Зависит от того, сколько можно заработать на деньгах за год (ставки дисконтирования). Если больше 20% — лучше сегодня, если меньше — через год.</div><div><b>Пояснение:</b> При ставке 20% 1,2 млн через год стоят сегодня ровно 1,2 / 1,2 = 1 млн.</div>"}, {"id": 1793123716192, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое дисконтирование?", "a": ["Что такое дисконтирование? Пересчёт будущих денег в сегодняшние: PV = CF / (1 + r)ᵗ. Пояснение: 100 через 2 года при ставке 10%: 100 / 1,1² = 83 сегодня."], "frontHtml": "<div>Что такое дисконтирование?</div>", "backHtml": "<div>Что такое дисконтирование?</div><hr><div>Пересчёт будущих денег в сегодняшние: PV = CF / (1 + r)ᵗ.</div><div><b>Пояснение:</b> 100 через 2 года при ставке 10%: 100 / 1,1² = 83 сегодня.</div>"}, {"id": 1793123716194, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое ставка дисконтирования?", "a": ["Что такое ставка дисконтирования? Доходность, которую инвесторы требуют за вложение в компанию с учётом её риска. Пояснение: Чем рискованнее бизнес, тем выше ставка и тем ниже стоимость будущих потоков сегодня."], "frontHtml": "<div>Что такое ставка дисконтирования?</div>", "backHtml": "<div>Что такое ставка дисконтирования?</div><hr><div>Доходность, которую инвесторы требуют за вложение в компанию с учётом её риска.</div><div><b>Пояснение:</b> Чем рискованнее бизнес, тем выше ставка и тем ниже стоимость будущих потоков сегодня.</div>"}, {"id": 1793123716196, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое WACC?", "a": ["Что такое WACC? Weighted Average Cost of Capital — средневзвешенная стоимость капитала: требуемая доходность акционеров и кредиторов, взвешенная по их долям. Пояснение: Ставка дисконтирования для FCFF. Стоимость долга берётся после налога — так учитывается налоговый щит."], "frontHtml": "<div>Что такое WACC?</div>", "backHtml": "<div>Что такое WACC?</div><hr><div>Weighted Average Cost of Capital — средневзвешенная стоимость капитала: требуемая доходность акционеров и кредиторов, взвешенная по их долям.</div><div><b>Пояснение:</b> Ставка дисконтирования для FCFF. Стоимость долга берётся после налога — так учитывается налоговый щит.</div>"}, {"id": 1793123716198, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Как выглядит формула DCF?", "a": ["Как выглядит формула DCF? PV = CF₁/(1+r)¹ + CF₂/(1+r)² + … + CFₙ/(1+r)ⁿ + TV/(1+r)ⁿ. Пояснение: Сумма приведённых потоков за прогнозный период плюс приведённая терминальная стоимость."], "frontHtml": "<div>Как выглядит формула DCF?</div>", "backHtml": "<div>Как выглядит формула DCF?</div><hr><div>PV = CF₁/(1+r)¹ + CF₂/(1+r)² + … + CFₙ/(1+r)ⁿ + TV/(1+r)ⁿ.</div><div><b>Пояснение:</b> Сумма приведённых потоков за прогнозный период плюс приведённая терминальная стоимость.</div>"}, {"id": 1793123716200, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое денежный поток и чем он отличается от стоимости компании?", "a": ["Что такое денежный поток и чем он отличается от стоимости компании? Денежный поток — деньги, которые компания приносит за один год. Стоимость — сколько сегодня стоит право получать все будущие потоки. Пояснение: Квартира приносит 600 тыс. аренды в год (поток), а стоит 10 млн (стоимость)."], "frontHtml": "<div>Что такое денежный поток и чем он отличается от стоимости компании?</div>", "backHtml": "<div>Что такое денежный поток и чем он отличается от стоимости компании?</div><hr><div>Денежный поток — деньги, которые компания приносит за один год. Стоимость — сколько сегодня стоит право получать все будущие потоки.</div><div><b>Пояснение:</b> Квартира приносит 600 тыс. аренды в год (поток), а стоит 10 млн (стоимость).</div>"}, {"id": 1793123716202, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое прогнозный период?", "a": ["Что такое прогнозный период? Годы, на которые денежные потоки прогнозируют подробно, по каждому году отдельно. Обычно 5–10 лет. Пояснение: Длится, пока компания не выйдет на стабильное состояние: рост замедлился до g, маржа и капекс устоялись."], "frontHtml": "<div>Что такое прогнозный период?</div>", "backHtml": "<div>Что такое прогнозный период?</div><hr><div>Годы, на которые денежные потоки прогнозируют подробно, по каждому году отдельно. Обычно 5–10 лет.</div><div><b>Пояснение:</b> Длится, пока компания не выйдет на стабильное состояние: рост замедлился до g, маржа и капекс устоялись.</div>"}, {"id": 1793123716204, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое терминальная стоимость (TV)?", "a": ["Что такое терминальная стоимость (TV)? Стоимость всех денежных потоков после прогнозного периода — с года n+1 и до бесконечности. Пояснение: Потоки за годы прогнозного периода в неё не входят — они считаются отдельно."], "frontHtml": "<div>Что такое терминальная стоимость (TV)?</div>", "backHtml": "<div>Что такое терминальная стоимость (TV)?</div><hr><div>Стоимость всех денежных потоков после прогнозного периода — с года n+1 и до бесконечности.</div><div><b>Пояснение:</b> Потоки за годы прогнозного периода в неё не входят — они считаются отдельно.</div>"}, {"id": 1793123716206, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Как считается TV по формуле Гордона?", "a": ["Как считается TV по формуле Гордона? TV = FCFₙ × (1 + g) / (r − g). Пояснение: Пример: FCF₅ = 140, g = 4%, WACC = 12% → TV = 140 × 1,04 / 0,08 = 1820."], "frontHtml": "<div>Как считается TV по формуле Гордона?</div>", "backHtml": "<div>Как считается TV по формуле Гордона?</div><hr><div>TV = FCFₙ × (1 + g) / (r − g).</div><div><b>Пояснение:</b> Пример: FCF₅ = 140, g = 4%, WACC = 12% → TV = 140 × 1,04 / 0,08 = 1820.</div>"}, {"id": 1793123716208, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "На какой момент времени считается TV и что с ней делают дальше?", "a": ["На какой момент времени считается TV и что с ней делают дальше? На конец последнего прогнозного года. Потом её дисконтируют к сегодняшнему дню: TV / (1 + r)ⁿ. Пояснение: Пример: TV = 1820 на конец 5-го года → 1820 / 1,12⁵ = 1033 сегодня. В EV идёт именно 1033."], "frontHtml": "<div>На какой момент времени считается TV и что с ней делают дальше?</div>", "backHtml": "<div>На какой момент времени считается TV и что с ней делают дальше?</div><hr><div>На конец последнего прогнозного года. Потом её дисконтируют к сегодняшнему дню: TV / (1 + r)ⁿ.</div><div><b>Пояснение:</b> Пример: TV = 1820 на конец 5-го года → 1820 / 1,12⁵ = 1033 сегодня. В EV идёт именно 1033.</div>"}, {"id": 1793123716210, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое g (TGR) в формуле терминальной стоимости?", "a": ["Что такое g (TGR) в формуле терминальной стоимости? Вечный темп роста денежных потоков после прогнозного периода (terminal growth rate). Пояснение: Задаётся как допущение: не выше долгосрочного роста экономики. В рублях обычно ~4–5%, в долларах ~2–3%. Обязательно g < WACC."], "frontHtml": "<div>Что такое g (TGR) в формуле терминальной стоимости?</div>", "backHtml": "<div>Что такое g (TGR) в формуле терминальной стоимости?</div><hr><div>Вечный темп роста денежных потоков после прогнозного периода (terminal growth rate).</div><div><b>Пояснение:</b> Задаётся как допущение: не выше долгосрочного роста экономики. В рублях обычно ~4–5%, в долларах ~2–3%. Обязательно g &lt; WACC.</div>"}, {"id": 1793123716212, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Какую долю стоимости обычно составляет TV и почему это важно?", "a": ["Какую долю стоимости обычно составляет TV и почему это важно? Обычно 60–80%, иногда больше. Пояснение: Поэтому оценка очень чувствительна к g и WACC: сдвиг g на 1 п.п. может изменить EV на ~10%."], "frontHtml": "<div>Какую долю стоимости обычно составляет TV и почему это важно?</div>", "backHtml": "<div>Какую долю стоимости обычно составляет TV и почему это важно?</div><hr><div>Обычно 60–80%, иногда больше.</div><div><b>Пояснение:</b> Поэтому оценка очень чувствительна к g и WACC: сдвиг g на 1 п.п. может изменить EV на ~10%.</div>"}, {"id": 1793123716214, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::5. DCF и терминальная стоимость", "q": "Что такое exit multiple (мультипликатор выхода)?", "a": ["Что такое exit multiple (мультипликатор выхода)? Второй способ расчёта TV: TV = мультипликатор × показатель последнего прогнозного года (например, EV/EBITDA × EBITDA). Пояснение: Как будто ты продаёшь компанию в конце прогноза по рыночному мультипликатору. Обычно считают и по Гордону, и по exit multiple и сверяют."], "frontHtml": "<div>Что такое exit multiple (мультипликатор выхода)?</div>", "backHtml": "<div>Что такое exit multiple (мультипликатор выхода)?</div><hr><div>Второй способ расчёта TV: TV = мультипликатор × показатель последнего прогнозного года (например, EV/EBITDA × EBITDA).</div><div><b>Пояснение:</b> Как будто ты продаёшь компанию в конце прогноза по рыночному мультипликатору. Обычно считают и по Гордону, и по exit multiple и сверяют.</div>"}, {"id": 1793123716216, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Что такое мультипликатор?", "a": ["Что такое мультипликатор? Отношение стоимости компании к её финансовому показателю: например, EV/EBITDA или P/E. Пояснение: Показывает, сколько рынок платит за единицу показателя. EV/EBITDA = 8x: за каждый рубль EBITDA платят 8 рублей."], "frontHtml": "<div>Что такое мультипликатор?</div>", "backHtml": "<div>Что такое мультипликатор?</div><hr><div>Отношение стоимости компании к её финансовому показателю: например, EV/EBITDA или P/E.</div><div><b>Пояснение:</b> Показывает, сколько рынок платит за единицу показателя. EV/EBITDA = 8x: за каждый рубль EBITDA платят 8 рублей.</div>"}, {"id": 1793123716218, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "На чём основан метод оценки по мультипликаторам?", "a": ["На чём основан метод оценки по мультипликаторам? На законе одной цены: похожие активы должны продаваться по похожим мультипликаторам. Пояснение: Аналогия со слайда 19: стена из 6 кирпичей по $10 стоит $60, значит, стена из 6 кирпичей по $20 стоит $120."], "frontHtml": "<div>На чём основан метод оценки по мультипликаторам?</div>", "backHtml": "<div>На чём основан метод оценки по мультипликаторам?</div><hr><div>На законе одной цены: похожие активы должны продаваться по похожим мультипликаторам.</div><div><b>Пояснение:</b> Аналогия со слайда 19: стена из 6 кирпичей по $10 стоит $60, значит, стена из 6 кирпичей по $20 стоит $120.</div>"}, {"id": 1793123716220, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Как оценить компанию по мультипликатору аналога?", "a": ["Как оценить компанию по мультипликатору аналога? EV₁ = (EV₂ / EBITDA₂) × EBITDA₁ — мультипликатор аналога, умноженный на показатель своей компании. Пояснение: Аналог: EV 1000, EBITDA 125 → 8x. Твоя EBITDA 50 → EV = 8 × 50 = 400."], "frontHtml": "<div>Как оценить компанию по мультипликатору аналога?</div>", "backHtml": "<div>Как оценить компанию по мультипликатору аналога?</div><hr><div>EV₁ = (EV₂ / EBITDA₂) × EBITDA₁ — мультипликатор аналога, умноженный на показатель своей компании.</div><div><b>Пояснение:</b> Аналог: EV 1000, EBITDA 125 → 8x. Твоя EBITDA 50 → EV = 8 × 50 = 400.</div>"}, {"id": 1793123716222, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Что такое EBITDA?", "a": ["Что такое EBITDA? Прибыль до вычета процентов, налогов и амортизации (Earnings Before Interest, Taxes, Depreciation and Amortization). Пояснение: Приблизительно показывает, сколько денег зарабатывает основной бизнес, независимо от долга и налогов."], "frontHtml": "<div>Что такое EBITDA?</div>", "backHtml": "<div>Что такое EBITDA?</div><hr><div>Прибыль до вычета процентов, налогов и амортизации (Earnings Before Interest, Taxes, Depreciation and Amortization).</div><div><b>Пояснение:</b> Приблизительно показывает, сколько денег зарабатывает основной бизнес, независимо от долга и налогов.</div>"}, {"id": 1793123716224, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Почему EV/EBITDA — самый популярный мультипликатор?", "a": ["Почему EV/EBITDA — самый популярный мультипликатор? Он не зависит от структуры капитала, налогов и амортизации, поэтому компании с разным долгом можно сравнивать напрямую. Пояснение: И EV, и EBITDA относятся ко всем инвесторам — до выплат по долгу."], "frontHtml": "<div>Почему EV/EBITDA — самый популярный мультипликатор?</div>", "backHtml": "<div>Почему EV/EBITDA — самый популярный мультипликатор?</div><hr><div>Он не зависит от структуры капитала, налогов и амортизации, поэтому компании с разным долгом можно сравнивать напрямую.</div><div><b>Пояснение:</b> И EV, и EBITDA относятся ко всем инвесторам — до выплат по долгу.</div>"}, {"id": 1793123716226, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Что такое P/E?", "a": ["Что такое P/E? Цена акции / прибыль на акцию (или капитализация / чистая прибыль). Пояснение: Делится Equity, а не EV, потому что чистая прибыль — уже после процентов, то есть принадлежит только акционерам."], "frontHtml": "<div>Что такое P/E?</div>", "backHtml": "<div>Что такое P/E?</div><hr><div>Цена акции / прибыль на акцию (или капитализация / чистая прибыль).</div><div><b>Пояснение:</b> Делится Equity, а не EV, потому что чистая прибыль — уже после процентов, то есть принадлежит только акционерам.</div>"}, {"id": 1793123716228, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Какое правило соответствия числителя и знаменателя в мультипликаторах?", "a": ["Какое правило соответствия числителя и знаменателя в мультипликаторах? EV делят на показатели до процентов (выручка, EBITDA, EBIT). Equity Value — на показатели после процентов (чистая прибыль). Пояснение: EV / чистая прибыль — ошибка: в числителе есть долг, а в знаменателе прибыль уже после выплат по нему."], "frontHtml": "<div>Какое правило соответствия числителя и знаменателя в мультипликаторах?</div>", "backHtml": "<div>Какое правило соответствия числителя и знаменателя в мультипликаторах?</div><hr><div>EV делят на показатели до процентов (выручка, EBITDA, EBIT). Equity Value — на показатели после процентов (чистая прибыль).</div><div><b>Пояснение:</b> EV / чистая прибыль — ошибка: в числителе есть долг, а в знаменателе прибыль уже после выплат по нему.</div>"}, {"id": 1793123716230, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Какие признаки бизнес-профиля учитывают при подборе аналогов?", "a": ["Какие признаки бизнес-профиля учитывают при подборе аналогов? Отрасль, продукты и услуги, клиенты и конечные рынки, каналы сбыта, география. Пояснение: Слайд 21, левая колонка. Отвечает на вопрос «чем компания занимается»."], "frontHtml": "<div>Какие признаки бизнес-профиля учитывают при подборе аналогов?</div>", "backHtml": "<div>Какие признаки бизнес-профиля учитывают при подборе аналогов?</div><hr><div>Отрасль, продукты и услуги, клиенты и конечные рынки, каналы сбыта, география.</div><div><b>Пояснение:</b> Слайд 21, левая колонка. Отвечает на вопрос «чем компания занимается».</div>"}, {"id": 1793123716232, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Какие признаки финансового профиля учитывают при подборе аналогов?", "a": ["Какие признаки финансового профиля учитывают при подборе аналогов? Размер, прибыльность, рост, отдача на инвестиции (ROIC/ROE), кредитный профиль (уровень долга). Пояснение: Слайд 21, правая колонка. Самый сильный фактор — рост: быстрорастущие компании торгуются с высокими мультипликаторами."], "frontHtml": "<div>Какие признаки финансового профиля учитывают при подборе аналогов?</div>", "backHtml": "<div>Какие признаки финансового профиля учитывают при подборе аналогов?</div><hr><div>Размер, прибыльность, рост, отдача на инвестиции (ROIC/ROE), кредитный профиль (уровень долга).</div><div><b>Пояснение:</b> Слайд 21, правая колонка. Самый сильный фактор — рост: быстрорастущие компании торгуются с высокими мультипликаторами.</div>"}, {"id": 1793123716234, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Почему важно учитывать географию при подборе аналогов?", "a": ["Почему важно учитывать географию при подборе аналогов? Компании развивающихся рынков (в т.ч. России) торгуются с дисконтом к западным из-за странового риска. Пояснение: EV/EBITDA российской компании 5x и американской 12x может быть нормой — сравнивать напрямую нельзя."], "frontHtml": "<div>Почему важно учитывать географию при подборе аналогов?</div>", "backHtml": "<div>Почему важно учитывать географию при подборе аналогов?</div><hr><div>Компании развивающихся рынков (в т.ч. России) торгуются с дисконтом к западным из-за странового риска.</div><div><b>Пояснение:</b> EV/EBITDA российской компании 5x и американской 12x может быть нормой — сравнивать напрямую нельзя.</div>"}, {"id": 1793123716236, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::6. Мультипликаторы", "q": "Как на практике выбирают мультипликатор для оценки?", "a": ["Как на практике выбирают мультипликатор для оценки? Берут 5–10 аналогов, считают медиану и диапазон, а потом сдвигают оценку вверх или вниз в зависимости от того, лучше или хуже компания аналогов. Пояснение: Если компания растёт быстрее и прибыльнее аналогов — её ставят ближе к верхней границе диапазона."], "frontHtml": "<div>Как на практике выбирают мультипликатор для оценки?</div>", "backHtml": "<div>Как на практике выбирают мультипликатор для оценки?</div><hr><div>Берут 5–10 аналогов, считают медиану и диапазон, а потом сдвигают оценку вверх или вниз в зависимости от того, лучше или хуже компания аналогов.</div><div><b>Пояснение:</b> Если компания растёт быстрее и прибыльнее аналогов — её ставят ближе к верхней границе диапазона.</div>"}, {"id": 1793123716238, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое benchmarking (слайд 24)?", "a": ["Что такое benchmarking (слайд 24)? Сравнение компании с аналогами по ключевым бизнес- и финансовым показателям в одной таблице. Пояснение: Пример: СИБУР против Dow, BASF, SABIC и др. Помогает понять, какие аналоги ближе и где компания сильнее или слабее."], "frontHtml": "<div>Что такое benchmarking (слайд 24)?</div>", "backHtml": "<div>Что такое benchmarking (слайд 24)?</div><hr><div>Сравнение компании с аналогами по ключевым бизнес- и финансовым показателям в одной таблице.</div><div><b>Пояснение:</b> Пример: СИБУР против Dow, BASF, SABIC и др. Помогает понять, какие аналоги ближе и где компания сильнее или слабее.</div>"}, {"id": 1793123716240, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Почему у СИБУРа в таблице benchmarking Market Cap и EV — «n/a»?", "a": ["Почему у СИБУРа в таблице benchmarking Market Cap и EV — «n/a»? Это частная компания, её акции не торгуются на бирже, поэтому рыночной стоимости нет — её и нужно оценить."], "frontHtml": "<div>Почему у СИБУРа в таблице benchmarking Market Cap и EV — «n/a»?</div>", "backHtml": "<div>Почему у СИБУРа в таблице benchmarking Market Cap и EV — «n/a»?</div><hr><div>Это частная компания, её акции не торгуются на бирже, поэтому рыночной стоимости нет — её и нужно оценить.</div>"}, {"id": 1793123716242, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое EBITDA margin?", "a": ["Что такое EBITDA margin? EBITDA / выручка — какая доля выручки остаётся в виде операционной прибыли. Пояснение: СИБУР: 2,8 / 7,8 = 35% — выше большинства аналогов благодаря дешёвому сырью."], "frontHtml": "<div>Что такое EBITDA margin?</div>", "backHtml": "<div>Что такое EBITDA margin?</div><hr><div>EBITDA / выручка — какая доля выручки остаётся в виде операционной прибыли.</div><div><b>Пояснение:</b> СИБУР: 2,8 / 7,8 = 35% — выше большинства аналогов благодаря дешёвому сырью.</div>"}, {"id": 1793123716244, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое D&A?", "a": ["Что такое D&A? Depreciation & Amortization — амортизация основных средств и нематериальных активов. Пояснение: Расход «на бумаге»: деньги не уходят, поэтому при расчёте FCFF её прибавляют обратно."], "frontHtml": "<div>Что такое D&amp;A?</div>", "backHtml": "<div>Что такое D&amp;A?</div><hr><div>Depreciation &amp; Amortization — амортизация основных средств и нематериальных активов.</div><div><b>Пояснение:</b> Расход «на бумаге»: деньги не уходят, поэтому при расчёте FCFF её прибавляют обратно.</div>"}, {"id": 1793123716246, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое EBIT?", "a": ["Что такое EBIT? Операционная прибыль: EBIT = EBITDA − D&A. Пояснение: Earnings Before Interest and Taxes — прибыль до процентов и налогов."], "frontHtml": "<div>Что такое EBIT?</div>", "backHtml": "<div>Что такое EBIT?</div><hr><div>Операционная прибыль: EBIT = EBITDA − D&amp;A.</div><div><b>Пояснение:</b> Earnings Before Interest and Taxes — прибыль до процентов и налогов.</div>"}, {"id": 1793123716248, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое NOPAT?", "a": ["Что такое NOPAT? Операционная прибыль после налога: NOPAT = EBIT × (1 − ставка налога). Пояснение: Net Operating Profit After Tax. На слайде 25: EBIT 96 → NOPAT 77 (налог 20%)."], "frontHtml": "<div>Что такое NOPAT?</div>", "backHtml": "<div>Что такое NOPAT?</div><hr><div>Операционная прибыль после налога: NOPAT = EBIT × (1 − ставка налога).</div><div><b>Пояснение:</b> Net Operating Profit After Tax. На слайде 25: EBIT 96 → NOPAT 77 (налог 20%).</div>"}, {"id": 1793123716250, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое Capex?", "a": ["Что такое Capex? Капитальные затраты — инвестиции в основные средства: строительство, оборудование. Пояснение: В FCFF вычитается, потому что это реальный отток денег."], "frontHtml": "<div>Что такое Capex?</div>", "backHtml": "<div>Что такое Capex?</div><hr><div>Капитальные затраты — инвестиции в основные средства: строительство, оборудование.</div><div><b>Пояснение:</b> В FCFF вычитается, потому что это реальный отток денег.</div>"}, {"id": 1793123716252, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое NWC и изменение NWC?", "a": ["Что такое NWC и изменение NWC? Net Working Capital — оборотный капитал: запасы + дебиторка − кредиторка. Рост NWC забирает деньги из потока, снижение — добавляет. Пояснение: Если клиенты стали платить позже, дебиторка растёт → деньги «заморожены» → FCFF меньше."], "frontHtml": "<div>Что такое NWC и изменение NWC?</div>", "backHtml": "<div>Что такое NWC и изменение NWC?</div><hr><div>Net Working Capital — оборотный капитал: запасы + дебиторка − кредиторка. Рост NWC забирает деньги из потока, снижение — добавляет.</div><div><b>Пояснение:</b> Если клиенты стали платить позже, дебиторка растёт → деньги «заморожены» → FCFF меньше.</div>"}, {"id": 1793123716254, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Как считается FCFF (по строкам слайда 25)?", "a": ["Как считается FCFF (по строкам слайда 25)? FCFF = NOPAT + D&A − Capex − ΔNWC. Пояснение: Пример 2018F: 77 + 114 − 222 + 5 ≈ −25. Поток отрицательный из-за большого капекса."], "frontHtml": "<div>Как считается FCFF (по строкам слайда 25)?</div>", "backHtml": "<div>Как считается FCFF (по строкам слайда 25)?</div><hr><div>FCFF = NOPAT + D&amp;A − Capex − ΔNWC.</div><div><b>Пояснение:</b> Пример 2018F: 77 + 114 − 222 + 5 ≈ −25. Поток отрицательный из-за большого капекса.</div>"}, {"id": 1793123716256, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Как в DCF-модели со слайда 25 получают Equity Value?", "a": ["Как в DCF-модели со слайда 25 получают Equity Value? PV потоков + PV TV = EV, затем EV − чистый долг = Equity. Пояснение: 1440 + 670 ≈ 2109 (EV) → 2109 − 972 = 1137 (Equity)."], "frontHtml": "<div>Как в DCF-модели со слайда 25 получают Equity Value?</div>", "backHtml": "<div>Как в DCF-модели со слайда 25 получают Equity Value?</div><hr><div>PV потоков + PV TV = EV, затем EV − чистый долг = Equity.</div><div><b>Пояснение:</b> 1440 + 670 ≈ 2109 (EV) → 2109 − 972 = 1137 (Equity).</div>"}, {"id": 1793123716258, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое таблица чувствительности (sensitivity)?", "a": ["Что такое таблица чувствительности (sensitivity)? Таблица, которая показывает, как меняется оценка при разных значениях двух ключевых допущений. Пояснение: На слайде 25: EV при разных WACC (11,6–15,6%) и exit multiple (4,5–8,5x) — от 1741 до 2556."], "frontHtml": "<div>Что такое таблица чувствительности (sensitivity)?</div>", "backHtml": "<div>Что такое таблица чувствительности (sensitivity)?</div><hr><div>Таблица, которая показывает, как меняется оценка при разных значениях двух ключевых допущений.</div><div><b>Пояснение:</b> На слайде 25: EV при разных WACC (11,6–15,6%) и exit multiple (4,5–8,5x) — от 1741 до 2556.</div>"}, {"id": 1793123716260, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что означают A, F, E и LTM рядом с годами?", "a": ["Что означают A, F, E и LTM рядом с годами? A — actual (факт), F/E — forecast/estimate (прогноз), LTM — last twelve months (последние 12 месяцев). Пояснение: 2018F — прогноз на 2018 год. EV/LTM EBITDA — EV, делённый на EBITDA за последние 12 месяцев."], "frontHtml": "<div>Что означают A, F, E и LTM рядом с годами?</div>", "backHtml": "<div>Что означают A, F, E и LTM рядом с годами?</div><hr><div>A — actual (факт), F/E — forecast/estimate (прогноз), LTM — last twelve months (последние 12 месяцев).</div><div><b>Пояснение:</b> 2018F — прогноз на 2018 год. EV/LTM EBITDA — EV, делённый на EBITDA за последние 12 месяцев.</div>"}, {"id": 1793123716262, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое deal value и stake в таблице сделок (слайд 27)?", "a": ["Что такое deal value и stake в таблице сделок (слайд 27)? Deal value — сумма сделки. Stake — купленная доля компании. Пояснение: Если куплено 70%, для мультипликатора пересчитывают EV на 100% компании."], "frontHtml": "<div>Что такое deal value и stake в таблице сделок (слайд 27)?</div>", "backHtml": "<div>Что такое deal value и stake в таблице сделок (слайд 27)?</div><hr><div>Deal value — сумма сделки. Stake — купленная доля компании.</div><div><b>Пояснение:</b> Если куплено 70%, для мультипликатора пересчитывают EV на 100% компании.</div>"}, {"id": 1793123716264, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое синергии?", "a": ["Что такое синергии? Дополнительная стоимость, которая появляется от объединения компаний: экономия на затратах или рост выручки. Пояснение: Пример со слайда 27: ожидаемые синергии от покупки Korsnäs — ~$40 млн в год (18% её EBITDA)."], "frontHtml": "<div>Что такое синергии?</div>", "backHtml": "<div>Что такое синергии?</div><hr><div>Дополнительная стоимость, которая появляется от объединения компаний: экономия на затратах или рост выручки.</div><div><b>Пояснение:</b> Пример со слайда 27: ожидаемые синергии от покупки Korsnäs — ~$40 млн в год (18% её EBITDA).</div>"}, {"id": 1793123716266, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Почему мультипликаторы сделок обычно выше торговых мультипликаторов?", "a": ["Почему мультипликаторы сделок обычно выше торговых мультипликаторов? В цену сделки входит премия за контроль и часть синергий. Пояснение: Покупатель получает управление компанией, а не просто пакет акций, — за это доплачивают."], "frontHtml": "<div>Почему мультипликаторы сделок обычно выше торговых мультипликаторов?</div>", "backHtml": "<div>Почему мультипликаторы сделок обычно выше торговых мультипликаторов?</div><hr><div>В цену сделки входит премия за контроль и часть синергий.</div><div><b>Пояснение:</b> Покупатель получает управление компанией, а не просто пакет акций, — за это доплачивают.</div>"}, {"id": 1793123716268, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое football field (Valuation Summary, слайд 28)?", "a": ["Что такое football field (Valuation Summary, слайд 28)? Итоговый график, где диапазоны стоимости по всем методам показаны полосами рядом друг с другом. Пояснение: Методы: текущая цена, VWAP, цели брокеров, DCF, comps, precedents. Сверху наносят предложенную цену сделки, чтобы видеть, дорого это или дёшево."], "frontHtml": "<div>Что такое football field (Valuation Summary, слайд 28)?</div>", "backHtml": "<div>Что такое football field (Valuation Summary, слайд 28)?</div><hr><div>Итоговый график, где диапазоны стоимости по всем методам показаны полосами рядом друг с другом.</div><div><b>Пояснение:</b> Методы: текущая цена, VWAP, цели брокеров, DCF, comps, precedents. Сверху наносят предложенную цену сделки, чтобы видеть, дорого это или дёшево.</div>"}, {"id": 1793123716270, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое brokers' target price?", "a": ["Что такое brokers' target price? Прогноз цены акции через 12 месяцев от аналитиков инвестбанков и брокеров. Пояснение: В football field берут диапазон или среднее по нескольким брокерам."], "frontHtml": "<div>Что такое brokers&#x27; target price?</div>", "backHtml": "<div>Что такое brokers&#x27; target price?</div><hr><div>Прогноз цены акции через 12 месяцев от аналитиков инвестбанков и брокеров.</div><div><b>Пояснение:</b> В football field берут диапазон или среднее по нескольким брокерам.</div>"}, {"id": 1793123716272, "topic": "5bd23fa2c7da7596", "sec": "Valuation — лекция IB Club::7. Примеры из приложения", "q": "Что такое implied EV/EBITDA в итоговой сводке оценки?", "a": ["Что такое implied EV/EBITDA в итоговой сводке оценки? Мультипликатор, который «заложен» в полученную оценку: оценка EV / EBITDA компании. Пояснение: Проверка здравого смысла: DCF дал EV 913 при EBITDA ~175 → 5,2x. Если implied-мультипликатор сильно выше рыночного, где-то ошибка."], "frontHtml": "<div>Что такое implied EV/EBITDA в итоговой сводке оценки?</div>", "backHtml": "<div>Что такое implied EV/EBITDA в итоговой сводке оценки?</div><hr><div>Мультипликатор, который «заложен» в полученную оценку: оценка EV / EBITDA компании.</div><div><b>Пояснение:</b> Проверка здравого смысла: DCF дал EV 913 при EBITDA ~175 → 5,2x. Если implied-мультипликатор сильно выше рыночного, где-то ошибка.</div>"}];